'use strict';

// v1226 realm map (Phil 30 Oct 2026: "put this map in game. Swap out the old one"): the 220x220 grid and its 0..100 % space
// are kept; Grok's realm art fills all 220 columns and the middle rows. The four continents ARE the four home regions, the
// island under the World Tree IS the worldtree zone, the islets are the wild, and every sea / off-realm cell is blocked.
// Which cell is which comes from ../world-realm.js, GENERATED by tools/realm/build_realm.py (never hand-edited).
// Initial placement is server-owned and never derived from the browser's save.
const crypto=require('node:crypto');
const REALM=require('../world-realm.js');
const GRID_COLS=220, CELL=100/GRID_COLS;
// col/row = the quadrant each continent sits in (0 west/north, 2 east/south)
const REGIONS=Object.freeze({
  crystor:{col:0,row:0},draymon:{col:2,row:0},
  tefron:{col:0,row:2},alumron:{col:2,row:2}
});
const REGION_KEYS=Object.freeze(Object.keys(REGIONS));
if(REALM.META.cols!==GRID_COLS) throw Error('world-realm.js is not a 220-column realm');
for(const k of REGION_KEYS) if(!REALM.zoneCells(k).length) throw Error('world-realm.js: region '+k+' has no land');
function cellIndex(v){ return Math.max(0,Math.min(GRID_COLS-1,Math.round(v/CELL-0.5))); }
function center(i){ return (i+0.5)*CELL; }
function zoneOf(x,y){ return REALM.zoneOfCell(cellIndex(x),cellIndex(y)); }
function isLand(x,y){ return REALM.isLand(cellIndex(x),cellIndex(y)); }
// Phil 30 Oct 2026: "the city should not be able to be teleported onto" - a city square is blocked like the sea
function isCity(x,y){ return REALM.isCity(cellIndex(x),cellIndex(y)); }
function cellKey(x,y){ return cellIndex(x)+','+cellIndex(y); }
function treeCore(x,y){
  const cx=cellIndex(x),cy=cellIndex(y),middle=GRID_COLS/2;
  return cx>=middle-2&&cx<=middle+1&&cy>=middle-2&&cy<=middle+1;
}
function targetAllowed(home,x,y){
  return !!REGIONS[home]&&Number.isFinite(x)&&Number.isFinite(y)&&x>=0&&x<=100&&y>=0&&y<=100
    &&isLand(x,y)&&!isCity(x,y)&&!treeCore(x,y)&&(!REGIONS[zoneOf(x,y)]||zoneOf(x,y)===home);
}
// a region's land cells, in row order; `preferred` is an index into that list (wraps)
function openInRegion(region,blocked=[],randomInt=crypto.randomInt,preferred){
  if(!REGIONS[region]) return null;
  const cells=REALM.zoneCells(region), occupied=new Set(blocked), n=cells.length;
  const start=preferred==null?randomInt(n):((preferred%n)+n)%n;
  for(let i=0;i<n;i++){
    const [cx,cy]=cells[(start+i)%n];
    if(!occupied.has(cx+','+cy)) return {region,x:center(cx),y:center(cy)};
  }
  return null;
}
// the nearest open land cell of the castle's OWN home region (the relocation rule: a castle the new map puts in the sea,
// or in another region, moves to the nearest land of its own region)
function nearestInRegion(home,x,y,blocked=[]){
  if(!REGIONS[home]||!Number.isFinite(x)||!Number.isFinite(y)) return null;
  const occupied=new Set(blocked), fromX=cellIndex(x), fromY=cellIndex(y);
  let best=null,bestDistance=Infinity;
  for(const [cx,cy] of REALM.zoneCells(home)){
    if(occupied.has(cx+','+cy)) continue;
    const distance=(cx-fromX)**2+(cy-fromY)**2;
    if(distance<bestDistance){ best={region:home,x:center(cx),y:center(cy)}; bestDistance=distance; }
  }
  return best;
}
// the nearest square this castle may stand on (own region, wild islets or the World Tree island)
function nearestOpen(home,x,y,blocked=[]){
  if(!REGIONS[home]||!Number.isFinite(x)||!Number.isFinite(y)) return null;
  const occupied=new Set(blocked);
  const fromX=cellIndex(x),fromY=cellIndex(y);
  let best=null,bestDistance=Infinity;
  for(let cy=0;cy<GRID_COLS;cy++) for(let cx=0;cx<GRID_COLS;cx++){
    const px=center(cx),py=center(cy),key=cx+','+cy;
    if(occupied.has(key)||!targetAllowed(home,px,py)) continue;
    const distance=(cx-fromX)**2+(cy-fromY)**2;
    if(distance<bestDistance){ best={region:home,x:px,y:py}; bestDistance=distance; }
  }
  return best;
}
function valid(loc){
  if(!loc||!REGIONS[loc.region]||!Number.isFinite(loc.x)||!Number.isFinite(loc.y)) return false;
  return targetAllowed(loc.region,loc.x,loc.y);
}
function place(existing,randomInt=crypto.randomInt,blocked=[]){
  const locations=(existing||[]).filter(valid);
  const occupied=new Set(locations.map(loc=>cellIndex(loc.x)+','+cellIndex(loc.y)));
  for(const key of blocked) occupied.add(key);
  const counts=Object.fromEntries(REGION_KEYS.map(k=>[k,0]));
  for(const loc of locations) counts[loc.region]++;
  // Fill the least populated home region first. Equal counts use a random tie break.
  const order=REGION_KEYS.map(region=>({region,count:counts[region],tie:randomInt(0x7fffffff)}))
    .sort((a,b)=>a.count-b.count||a.tie-b.tie);
  for(const {region} of order){
    const cells=REALM.zoneCells(region), n=cells.length, start=randomInt(n);
    for(let i=0;i<n;i++){
      const [cx,cy]=cells[(start+i)%n];
      if(!occupied.has(cx+','+cy)) return {region,x:center(cx),y:center(cy)};
    }
  }
  throw Error('No free castle square remains in the home regions.');
}
module.exports={GRID_COLS,CELL,REGIONS,REGION_KEYS,REALM,cellIndex,center,zoneOf,
  isLand,isCity,cellKey,treeCore,targetAllowed,openInRegion,nearestInRegion,nearestOpen,valid,place};
